using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Circle.FourNegative.SecondPeakIndependentTailInterior;
internal sealed class SupportsDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Native low-bit physical inventory", H("Four exhaustive disjoint support partitions"),
        Blocks(Paragraph(Text("Put r=a-c-d, s=b-a-1 and q=2^s. The U bank-zero support is range(d-3) when c=2 and the single bit d-c-1 otherwise. Bank two contains bit d-3; bank one is their complement in range(d-1). V is wholly in bank zero. W bank zero is the exact binary support of a mask W0, bank two is its complement in range(s+2), and bank three is range(b-1) outside range(s+2). If r=0 then W0 is 4q-1 at c=2, floor(7q/2)-1 at c=3, and floor(3q/2)-1 at c>=4. If r=1 it is 4q-1 at c=2 and 2q-1 otherwise; r=2 gives 3q-1, and r>=3 gives q-1. The half-integer rounding error is one half exactly when q=1, and zero otherwise. X bank one contains bit a-3 and bank three contains bit zero. Its bank-zero support is {d-3} at r=0,c=2, {d-3,1} at r=0,c=3, {d-3,c-2,c-3} at r=0,c>=4, {d-2,1} at r=1,c=2, {d-2,c-1,c-2} at r=1,c>=3, {d-1,c,c-1} at r=2, and {r+d-3,r+c-2,r+c-3,r-2} at r>=3. Every such bit is positive and below a-3. X bank two is the complement of these three disjoint masks in range(a-1). These exact support partitions include empty masks. Summing their distinct powers of two and decoding chamberLabels proves that every physical nonterminal occurrence appears exactly once."))), []));
}
